import time
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration constants
ADC_I2C_ADDRESS = 0x48
ADC_GAIN = 1  # +/- 4.096V gain
READ_INTERVAL_SECONDS = 0.5

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        sys.exit(1)

def initialize_adc(i2c_bus, address=ADC_I2C_ADDRESS, gain=ADC_GAIN):
    """Initialize the ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus, address=address, gain=gain)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        sys.exit(1)

def read_adc_channels(adc_device):
    """Read all four ADC channels and return their values as a list."""
    channel_values = []
    for channel in range(4):
        try:
            analog_input = AnalogIn(adc_device, channel=channel)
            channel_values.append(analog_input.value)
        except Exception as e:
            print(f"Error reading channel {channel}: {e}")
            channel_values.append(None)  # Append None to maintain list length
    return channel_values

def format_channel_output(channel_values):
    """Format the ADC channel values for output."""
    output_lines = []
    header_line = "Channel | Value\n" + "-" * 15
    output_lines.append(header_line)

    for index, value in enumerate(channel_values):
        if value is not None:
            output_lines.append(f"{index}       | {value}\n")
        else:
            output_lines.append(f"{index}       | Error\n")
    return output_lines

def print_adc_output(output_lines):
    """Print the formatted ADC output to the console."""
    print("".join(output_lines))

def main():
    """Main function to read and display ADC values."""
    i2c_bus = initialize_i2c()
    adc_device = initialize_adc(i2c_bus)

    try:
        while True:
            adc_values = read_adc_channels(adc_device)
            output_lines = format_channel_output(adc_values)
            print_adc_output(output_lines)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or ADC in this library
        # but including a general exception block for robustness
        pass

if __name__ == "__main__":
    main()

