#!/usr/bin/env python3

import os
import time
import logging
import signal
import sys
from functools import partial
from typing import Callable, List, Optional, Tuple

import click
from PIL import Image, ImageOps, UnidentifiedImageError

from luma.core.interface import Interface
from luma.core.render import render
from luma.core.terminal import ascii_font

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_GIF_FOLDER = '/home/pi/gifs'
DEFAULT_DISPLAY_WIDTH = 128
DEFAULT_DISPLAY_HEIGHT = 64
DEFAULT_INTERVAL = 5
DEFAULT_LOOP_COUNT = 0  # Infinite loop

# Type definitions
ImageFrame = Tuple[Image.Image, int]  # PIL Image and duration in milliseconds
GifPlaybackHandler = Callable[[List[ImageFrame], int, int, int], None]  # Function to handle GIF playback


def validate_gif_file(file_path: str) -> None:
    """Validates that the given file is a GIF."""
    try:
        img = Image.open(file_path)
        if not img.is_animated:
            raise ValueError(f"File {file_path} is not an animated GIF.")
    except (FileNotFoundError, UnidentifiedImageError, ValueError) as e:
        raise click.FileError(file_path, hint=str(e))


def load_gif_files(gif_folder: str) -> List[str]:
    """Loads GIF file paths from the specified folder."""
    try:
        gif_files = [os.path.join(gif_folder, f) for f in os.listdir(gif_folder) if
                     os.path.isfile(os.path.join(gif_folder, f)) and f.lower().endswith('.gif')]
        if not gif_files:
            raise ValueError(f"No GIF files found in {gif_folder}")
        return gif_files
    except FileNotFoundError as e:
        raise click.DirectoryError(gif_folder, hint=str(e))
    except ValueError as e:
        raise click.ClickException(str(e))


def preload_gif(file_path: str) -> ImageFrame:
    """Preloads a GIF file and returns the duration of each frame."""
    try:
        img = Image.open(file_path)
        if not img.is_animated:
            raise ValueError(f"File {file_path} is not an animated GIF.")

        duration = img.info.get('duration', DEFAULT_INTERVAL)  # Get duration, default to DEFAULT_INTERVAL
        return img, duration
    except (FileNotFoundError, UnidentifiedImageError, ValueError) as e:
        raise click.FileError(file_path, hint=str(e))


def prepare_frames(img: Image.Image, display_width: int, display_height: int) -> List[Image.Image]:
    """Converts a GIF frame to a display-friendly format."""
    try:
        # Resize the image, maintaining aspect ratio
        width, height = img.size
        if width > height:
            new_height = int(height * (display_width / width))
            resized_img = img.resize((display_width, new_height), Image.NEAREST)
        else:
            new_width = int(width * (display_height / height))
            resized_img = img.resize((new_width, display_height), Image.NEAREST)

        # Pad the image to the display size, centering it
        padded_img = ImageOps.pad(resized_img, (display_width, display_height),
                                  method=Image.NEAREST, color='black', centering=(0.5, 0.5))

        return [padded_img]
    except UnidentifiedImageError as e:
        logger.error(f"Error preparing frame: {e}")
        return []



def display_frame(interface: Interface, frame: Image.Image) -> None:
    """Displays a single frame on the OLED."""
    try:
        render(interface, frame)
    except Exception as e:
        logger.error(f"Display error: {e}")



def play_gif(frame_generator: Callable[[int], Optional[ImageFrame]], loop_count: int) -> None:
    """Plays an animated GIF on the display, handling frame generation and timing."""
    frame_index = 0
    start_time = time.monotonic()
    current_time = start_time

    while True:  # Loop indefinitely within this function
        frame = frame_generator(frame_index)
        if frame is None:
            break  # End of GIF or error

        img, duration = frame
        display_frame(interface, img) # Display the frame

        frame_index += 1
        current_time = time.monotonic()
        sleep_time = max(0, duration / 1000 - (current_time - start_time))  # Avoid negative sleep
        time.sleep(sleep_time)
        start_time = current_time

        if loop_count > 0:
            loop_count -= 1
            if loop_count == 0:
                break # Exit loop after specified number of loops



def advance_to_next_file(current_index: int, file_list: List[str]) -> int:
    """Advances to the next GIF file in the list, handling circular indexing."""
    return (current_index + 1) % len(file_list)


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logger.info("Shutting down...")
    global running
    running = False
    sys.exit(0)


def run_animation(file_list: List[str], interval: int, loop_count: int, interface: Interface) -> None:
    """Runs the main animation loop."""
    global running

    def frame_generator(file_index: int) -> Optional[ImageFrame]:
        """Generator function to yield frames from the current GIF file."""
        if not running:
            return None

        try:
            file_path = file_list[file_index]
            img, duration = preload_gif(file_path)
            frames = prepare_frames(img, interface.width, interface.height)
            if not frames:
                logger.warning(f"Failed to prepare frames for {file_path}")
                return None

            return frames[0], duration  # Return only the duration
        except Exception as e:
            logger.error(f"Error generating frames: {e}")
            return None

    try:
        running = True
        while running:
            play_gif(frame_generator, loop_count) # Play the current GIF
            if not running:
                break
    except Exception as e:
        logger.exception(f"Unhandled exception in animation loop: {e}")
    finally:
        logger.info("Animation finished.")


def main(gif_folder: str, interval: int, loop_count: int, display_width: int, display_height: int) -> None:
    """Main function to initialize and run the animation."""
    global interface
    try:
        gif_files = load_gif_files(gif_folder)
        interface = None  # Initialize interface outside the try block
        interface = Interface(width=display_width, height=display_height)  # Initialize interface here
        run_animation(gif_files, interval, loop_count, interface)
    except Exception as e:
        logger.exception(f"Application error: {e}")
    finally:
        if interface:
            interface.cleanup()


@click.command()
@click.option('--gif_folder', '-d', default=DEFAULT_GIF_FOLDER, help='Path to the GIF folder')
@click.option('--interval', '-i', type=float, default=DEFAULT_INTERVAL, help='Frame duration in seconds')
@click.option('--loop_count', '-l', type=int, default=DEFAULT_LOOP_COUNT, help='Number of loops (0 for infinite)')
@click.option('--display_width', '-w', type=int, default=DEFAULT_DISPLAY_WIDTH, help='Display width')
@click.option('--display_height', '-h', type=int, default=DEFAULT_DISPLAY_HEIGHT, help='Display height')
def cli(gif_folder: str, interval: int, loop_count: int, display_width: int, display_height: int):
    """Command-line interface for the Raspberry Pi animation."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    main(gif_folder, interval * 1000, loop_count, display_width, display_height)


if __name__ == '__main__':
    cli()

