import time
import board
import busio
import adafruit_ssd1306
import adafruit_dht

# Configuration for the OLED display
OLED_WIDTH = 128
OLED_HEIGHT = 64
OLED_BORDER = 5

def initialize_i2c():
    """Initialize the I2C bus."""
    return busio.I2C(board.SCL, board.SDA)

def initialize_oled(i2c_bus):
    """Initialize the OLED display."""
    return adafruit_ssd1306.SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c_bus)

def initialize_dht_sensor(pin):
    """Initialize the DHT22 sensor."""
    return adafruit_dht.DHT22(pin)

def read_sensor_data(sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as error:
        print(f"Sensor read error: {error}")
        return None, None

def display_data(oled_display, temperature, humidity):
    """Display temperature and humidity on the OLED screen."""
    oled_display.fill(0)  # Clear the display
    oled_display.text(f"Temp: {temperature:.1f}C", 0, 0, 1)
    oled_display.text(f"Humidity: {humidity:.1f}%", 0, 16, 1)
    oled_display.show()  # Update the display

def main():
    """Main function to read sensor data and display it on the OLED screen."""
    i2c_bus = initialize_i2c()
    oled_display = initialize_oled(i2c_bus)
    dht_sensor = initialize_dht_sensor(board.D4)

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)
            if temperature is not None and humidity is not None:
                display_data(oled_display, temperature, humidity)
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        oled_display.fill(0)
        oled_display.show()
        i2c_bus.deinit()

if __name__ == "__main__":
    main()

