import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except ValueError as e:
    print(f"Error initializing I2C: {e}")
    exit()

# Initialize the I2C multiplexer
try:
    multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except ValueError as e:
    print(f"Error initializing multiplexer: {e}")
    exit()

# Initialize the BME280 sensor on channel 0
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0])
    bme280_sensor.sea_level_pressure = 1013.25  # Standard sea level pressure
except ValueError as e:
    print(f"Error initializing BME280 sensor: {e}")
    bme280_sensor = None  # Set to None to indicate failure

# Initialize the TSL2591 sensor on channel 1
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1])
except ValueError as e:
    print(f"Error initializing TSL2591 sensor: {e}")
    tsl2591_sensor = None  # Set to None to indicate failure

# Main loop to read and print sensor data
try:
    while True:
        # Read temperature, humidity, and pressure from BME280
        if bme280_sensor:
            try:
                temperature_c = bme280_sensor.temperature
                humidity_percent = bme280_sensor.humidity
