import time
import board
import adafruit_bmp280
import busio

# I2C setup for Raspberry Pi
i2c_bus = busio.I2C(board.SCL, board.SDA)

# BMP280 sensor setup
try:
    bmp280 = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=0x76)
except ValueError:
    print("BMP280 sensor not found. Check I2C connection.")
    exit()

# Function to collect baseline pressure readings
def collect_baseline():
    baseline_readings = []
    print("Collecting baseline pressure for 10 seconds...")
    for _ in range(10):
        try:
            baseline_readings.append(bmp280.pressure)
            time.sleep(1)
        except OSError:
            print("Error reading pressure. Check sensor connection.")
            time.sleep(1)  # Wait before retrying
    return baseline_readings

# Function to calculate average baseline pressure
def calculate_average(baseline_readings):
    if not baseline_readings:
        return 0  # Handle the case of no valid readings
    valid_readings = [p for p in baseline_readings if p is not None] # Filter out None values
    if not valid_readings:
        return 0 # Handle the case of all readings being None
    return sum(valid_readings) / len(valid_readings)

# Main program loop
if __name__ == "__main__":
    try:
        baseline_pressures = collect_baseline()
        baseline_pressure = calculate_average(baseline_pressures)
        print(f"Established baseline pressure: {baseline_pressure:.2f} hPa")

        while True:
            try:
                altitude = bmp280.altitude
                print(f"Relative altitude: {altitude:.2f} meters")
                time.sleep(1)
            except OSError:
                print("Error reading altitude. Check sensor connection.")
                time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        bmp280.close()

