import time
import requests
import adafruit_dht
import board

# Configuration
DHT_PIN = board.D4  # GPIO4 (physical pin 7)
SERVER_URL = 'http://127.0.0.1:5000/data'
READ_INTERVAL = 5  # seconds

def read_sensor_data(dht_device):
    """Reads temperature and humidity from the DHT sensor."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        return temperature, humidity
    except RuntimeError as error:
        print(f"Sensor read error: {error}")
        return None, None
    except Exception as error:
        print(f"Unexpected error: {error}")
        return None, None

def send_data_to_server(temperature, humidity):
    """Sends temperature and humidity data to the server."""
    payload = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(SERVER_URL, json=payload)
        print(f"Server response: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Network error: {e}")

def main():
    """Main function to read sensor data and send it to the server."""
    dht_device = adafruit_dht.DHT11(DHT_PIN)

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_device)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data_to_server(temperature, humidity)

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific resources to release for DHT11, but good practice to include a finally block
        print("Exiting program.")

if __name__ == "__main__":
    main()

