# Environmental monitoring script for Raspberry Pi 4 Model B
# Reads temperature and humidity from a UART sensor and alerts on thresholds

import serial
import time

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD_C = 30.0
HUMIDITY_THRESHOLD_PERCENT = 70.0
READ_INTERVAL_SECONDS = 1

def read_sensor_data(serial_connection):
    """Reads a line from the serial port and parses temperature and humidity."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature_c, humidity_percent = line.split(',')
            return float(temperature_c), float(humidity_percent)
        return None, None
    except ValueError:
        print("Error: Malformed data received from sensor.")
        return None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def check_thresholds(temperature_c, humidity_percent):
    """Checks if temperature or humidity exceeds predefined thresholds."""
    alert_message = ""
    if temperature_c is not None and temperature_c > TEMPERATURE_THRESHOLD_C:
        alert_message += f"High temperature: {temperature_c:.1f}C "
    if humidity_percent is not None and humidity_percent > HUMIDITY_THRESHOLD_PERCENT:
        alert_message += f"High humidity: {humidity_percent:.1f}% "
    return alert_message

def main():
    """Main function to read sensor data and check thresholds."""
    serial_connection = None
    try:
        # Initialise serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print("Environmental monitoring started. Press Ctrl+C to exit.")

        while True:
            temperature_c, humidity_percent = read_sensor_data(serial_connection)

            if temperature_c is not None and humidity_percent is not None:
                print(f"Temperature: {temperature_c:.1f}C, Humidity: {humidity_percent:.1f}%")

                alert_message = check_thresholds(temperature_c, humidity_percent)
                if alert_message:
                    print(f"ALERT: {alert_message}")

            time.sleep(READ_INTERVAL_SECONDS)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure serial port is closed on exit
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

