import RPi.GPIO as GPIO
import time
import requests

# Define the GPIO pin connected to the voltage sensor
VOLTAGE_SENSOR_PIN = 17

# Define the URL to send alerts to
ALERT_ENDPOINT = 'http://example.com/alert'

def initialize_gpio(pin):
    """Set up the GPIO pin for voltage monitoring."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def check_power_status(pin):
    """Read the voltage status from the GPIO pin."""
    return GPIO.input(pin)

def send_power_failure_alert(url):
    """Send an HTTP POST request to the alert endpoint."""
    try:
        requests.post(url, json={'alert': 'Power failure detected'})
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}")

def monitor_power(pin, alert_url, interval=1):
    """Monitor the power status and send alerts if necessary."""
    try:
        while True:
            status = check_power_status(pin)
            if not status:
                print('Power failure detected!')
                send_power_failure_alert(alert_url)
            else:
                print('Power is present.')
            time.sleep(interval)
    except KeyboardInterrupt:
        print('Monitoring stopped by user.')
    finally:
        GPIO.cleanup()
        print('GPIO cleanup completed.')

if __name__ == "__main__":
    initialize_gpio(VOLTAGE_SENSOR_PIN)
    monitor_power(VOLTAGE_SENSOR_PIN, ALERT_ENDPOINT)

