import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for GPIO pins (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol Constants
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing constants (seconds)
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1  # Timeout in seconds for reception


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful exit."""
    logging.info('Exiting program...')
    GPIO.cleanup()
    sys.exit(0)


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def buffer_to_char(buffer):
