def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error during I2C initialization: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor object."""
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return fingerprint_sensor
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error during fingerprint sensor initialization: {e}")
        return None

def authenticate_fingerprint(fingerprint_sensor):
    """Captures a fingerprint image and attempts to authenticate it."""
    try:
        print('Waiting for finger...')
        while fingerprint_sensor.get_image() != adafruit_fingerprint.OK:
            pass

        print('Creating template...')
        if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            return False

        print('Searching...')
        if fingerprint_sensor.finger_search() != adafruit_fingerprint.OK:
            return False

        return True
    except Exception as e:
        print(f"Error during fingerprint authentication: {e}")
        return False

def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("I2C initialization failed. Exiting.")
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        print("Fingerprint sensor initialization failed. Exiting.")
        return

    try:
        while True:
            if authenticate_fingerprint(fingerprint_sensor):
                print('Access Granted')
                # Add code to grant access (e.g., unlock a door, grant network access)
            else:
                print('Access Denied')

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for I2C or the fingerprint sensor library
        # in this case, but including a finally block for potential future expansion.
        print("Cleaning up resources (if needed).")
        # i2c_bus.deinit() # Uncomment if other devices need the bus
        print("Program finished.")

if __name__ == "__main__":
    main()

