import socket
import json
import time
import logging
import os
import signal
import sys
from datetime import datetime

try:
    import gps3
    from gps3 import gps3_socket
    from gps3 import gps3_ublox
    import serial
    import smbus2
    from gpiozero import LED
except ImportError as e:
    print(f"Missing required library: {e}.  Install with: pip install {e.name}")
    sys.exit(1)


# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_GPS_PORT = "/dev/ttyAMA0"
DEFAULT_GPS_BAUDRATE = 9600
DEFAULT_GPS_I2C_ADDRESS = 0x42
DEFAULT_GPS_TYPE = "uart"  # or "i2c"
DEFAULT_LISTEN_ADDRESS = "127.0.0.1"
DEFAULT_LISTEN_PORT = 9099
TRACKING_STATE_FILE = "tracking_state.txt"

# Global variables
tracking_state = "stopped"
gps_module = None  # Will be initialized based on configuration
gps_data = {"lat": 0.0, "lon": 0.0, "timestamp": None}


def load_tracking_state():
    """Loads the tracking state from a file."""
    global tracking_state
    try:
        with open(TRACKING_STATE_FILE, "r") as f:
            tracking_state = f.read().strip()
        logging.info(f"Loaded tracking state: {tracking_state}")
    except FileNotFoundError:
        logging.warning("Tracking state file not found. Starting with 'stopped'.")
        tracking_state = "stopped"
    except Exception as e:
        logging.error(f"Error loading tracking state: {e}. Starting with 'stopped'.")
        tracking_state = "stopped"


def save_tracking_state():
    """Saves the tracking state to a file."""
    try:
        with open(TRACKING_STATE_FILE, "w") as f:
            f.write(tracking_state)
        logging.info(f"Saved tracking state: {tracking_state}")
    except Exception as e:
        logging.error(f"Error saving tracking state: {e}")


def read_gps_position():
    """Reads GPS data from the configured GPS module."""
    global gps_data
    try:
        if gps_module:
            if isinstance(gps_module, gps3_socket.GPSDSocket):
                for raw_data in gps_module:
                    if raw_data:
                        gps_data = json.loads(raw_data)  # Simulate parsing
                        gps_data["timestamp"] = datetime.now().isoformat()
                        logging.debug(f"GPS data: {gps_data}")
                        return gps_data
            elif isinstance(gps_module, gps3_ublox.UBLOX):
                for raw_data in gps_module:
                    if raw_data:
                        gps_data = json.loads(raw_data)  # Simulate parsing
                        gps_data["timestamp"] = datetime.now().isoformat()
                        logging.debug(f"GPS data: {gps_data}")
                        return gps_data
            else:
                logging.warning("Unknown GPS type.")
                return None
        else:
            logging.warning("GPS module not initialized.")
            return None
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None
    except smbus2.SMBusError as e:
        logging.error(f"I2C communication error: {e}")
        return None
    except Exception as e:
        logging.error(f"Error reading GPS data: {e}")
        return None
    return None


def handle_command(command):
    """Handles a received command."""
    global tracking_state, gps_data
    try:
        if command == "start":
            if tracking_state == "stopped":
                tracking_state = "running"
                logging.info("Tracking started.")
            else:
                logging.warning("Tracking already running.")
        elif command == "stop":
            if tracking_state == "running":
                tracking_state = "stopped"
                logging.info("Tracking stopped.")
            else:
                logging.warning("Tracking already stopped.")
        elif command == "report":
            if gps_data["timestamp"]:
                print(json.dumps(gps_data))
            else:
                print(json.dumps({"error": "No GPS data available"}))
        else:
            logging.warning(f"Unknown command: {command}")
    except Exception as e:
        logging.error(f"Error handling command '{command}': {e}")


def handle_client(client_socket):
    """Handles a client connection."""
    try:
        while True:
            data = client_socket.recv(1024)
            if not data:
                break
            command = data.decode().strip()
            logging.info(f"Received command: {command}")
            handle_command(command)
    except Exception as e:
        logging.error(f"Error handling client: {e}")
    finally:
        client_socket.close()


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info("Shutting down gracefully...")
    global gps_module
    if gps_module:
        if isinstance(gps_module, serial.Serial):
            gps_module.close()
        elif isinstance(gps_module, smbus2.SMBus):
            gps_module.close()
    save_tracking_state()
    sys.exit(0)


def main():
    """Main function to run the IoT gateway."""
    global gps_module

    # Load tracking state
    load_tracking_state()

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Configure GPS module
    gps_type = os.environ.get("GPS_TYPE", DEFAULT_GPS_TYPE)
    if gps_type == "uart":
        gps_port = os.environ.get("GPS_PORT", DEFAULT_GPS_PORT)
        gps_baudrate = int(os.environ.get("GPS_BAUDRATE", DEFAULT_GPS_BAUDRATE))
        try:
            gps_module = serial.Serial(gps_port, baudrate=gps_baudrate, timeout=1)
            logging.info(f"Using UART GPS on {gps_port} at {gps_baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to initialize UART GPS: {e}")
            gps_module = None
    elif gps_type == "i2c":
        gps_i2c_address = int(os.environ.get("GPS_I2C_ADDRESS", DEFAULT_GPS_I2C_ADDRESS))
        try:
            gps_module = smbus2.SMBus(1)  # Use I2C bus 1
            logging.info(f"Using I2C GPS at address 0x{gps_i2c_address:02X}.")
        except smbus2.SMBusError as e:
            logging.error(f"Failed to initialize I2C GPS: {e}")
            gps_module = None
    else:
        logging.error(f"Invalid GPS type: {gps_type}")
        gps_module = None

    # Initialize GPS socket
    if gps_module:
        if isinstance(gps_module, serial.Serial):
            gps_socket = gps3_socket.GPSDSocket(port=gps_port)
        elif isinstance(gps_module, smbus2.SMBus):
            gps_socket = gps3_ublox.UBLOX(bus=gps_module, addr=gps_i2c_address)
        else:
            gps_socket = None
    else:
        gps_socket = None

    # Start GPS data stream
    if gps_socket:
        try:
            gps_socket.connect()
            gps_socket.watch()
        except Exception as e:
            logging.error(f"Failed to start GPS data stream: {e}")
            gps_socket = None

    # Create and bind the listening socket
    listen_address = os.environ.get("LISTEN_ADDRESS", DEFAULT_LISTEN_ADDRESS)
    listen_port = int(os.environ.get("LISTEN_PORT", DEFAULT_LISTEN_PORT))
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)  # Allow reuse of address
    try:
        server_socket.bind((listen_address, listen_port))
        server_socket.listen(1)
        logging.info(f"Listening for remote control commands on {listen_address}:{listen_port}")
    except socket.error as e:
        logging.error(f"Failed to bind to {listen_address}:{listen_port}: {e}")
        sys.exit(1)

    # Main loop
    try:
        while True:
            # Accept a client connection
            client_socket, client_address = server_socket.accept()
            logging.info(f"Accepted connection from {client_address}")
            handle_client(client_socket)

            # Read GPS data
            if gps_socket:
                gps_data = read_gps_position()

            # Sleep to avoid busy-waiting
            time.sleep(2)

    except KeyboardInterrupt:
        logging.info("Shutting down...")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Clean up resources
        if gps_module:
            if isinstance(gps_module, serial.Serial):
                gps_module.close()
            elif isinstance(gps_module, smbus2.SMBus):
                gps_module.close()
        server_socket.close()
        save_tracking_state()
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    main()

