#!/usr/bin/python3
"""
Simple DC Motor control with Adafruit DC Motor HAT.
"""

import atexit
import logging
import signal
import sys

from Adafruit_MotorHAT import Adafruit_MotorHAT, RELEASE, FORWARD, BACKWARD

# Set up logging (prints messages to the console)
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Constants
DC_MOTOR_MAX_SPEED = 255
DC_MOTOR_MIN_SPEED = -255
DEFAULT_PWM_FREQUENCY = 60  # Reduced frequency for quieter operation
MOTOR_NUMBERS = range(1, 5)  # Valid motor numbers (1-4)

class DCMotorHATExtra(Adafruit_MotorHAT):
    """
    Extends the standard Adafruit_MotorHAT class with extra features.
    """

    def __init__(self, i2c_addr=0x60, i2c_bus=1, freq=DEFAULT_PWM_FREQUENCY):
        """Initializes the motor HAT."""
        try:
            super().__init__(addr=i2c_addr, busnum=i2c_bus)
            self._initialize_motors()
            self.set_pwm_freq(freq)
            self._cleanup_motor_on_exit()  # Register cleanup function
            logging.info("Motor HAT initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing Motor HAT: {e}")
            sys.exit(1)


    def _initialize_motors(self):
        """Saves motor objects for later use."""
        self.motors = {}
        for motor_num in MOTOR_NUMBERS:
            self.motors[motor_num] = None

    def _cleanup_motor_on_exit(self):
        """Registers a function to stop motors on program exit."""
        atexit.register(self._cleanup)

    def _cleanup(self):
        """Stops all motors."""
        logging.info("Cleaning up motors...")
        for motor_num in MOTOR_NUMBERS:
            self.stop(motor_num)
        logging.info("Cleanup complete.")


    def set_pwm_freq(self, freq):
        """Sets the PWM frequency for all motors."""
        try:
            super().setPWMFreq(freq)
            logging.info(f"PWM frequency set to {freq} Hz")
            return True
        except Exception as e:
            logging.error(f"Error setting PWM frequency: {e}")
            return False

    def get_pwm_freq(self):
        """Gets the current PWM frequency."""
        return self._freq

    def get_max_duty_cycle(self):
        """Returns the maximum duty cycle value."""
        return DC_MOTOR_MAX_SPEED

    def get_min_duty_cycle(self):
        """Returns the minimum duty cycle value."""
        return DC_MOTOR_MIN_SPEED

    def is_duty_cycle_valid(self, duty_cycle):
        """Checks if a duty cycle value is within the valid range."""
        return DC_MOTOR_MIN_SPEED <= duty_cycle <= DC_MOTOR_MAX_SPEED


    def _get_motor(self, motor_num):
        """Retrieves the motor object, creating it if it doesn't exist."""
        if not 1 <= motor_num <= 4:
            raise ValueError("Invalid motor number. Must be between 1 and 4.")

        if self.motors[motor_num] is None:
            try:
                self.motors[motor_num] = self.getMotor(motor_num)
                logging.info(f"Motor {motor_num} initialized.")
            except Exception as e:
                logging.error(f"Error initializing motor {motor_num}: {e}")
                raise
        return self.motors[motor_num]


    def set_dc(self, motor_num, duty_cycle):
        """Sets the duty cycle for a specific motor."""
        if not self.is_duty_cycle_valid(duty_cycle):
            raise ValueError("Invalid duty cycle. Must be between -255 and 255.")

        try:
            motor = self._get_motor(motor_num)

            if duty_cycle == 0:
                motor.run(RELEASE)
                logging.debug(f"Motor {motor_num} stopped.")
            else:
                direction = FORWARD if duty_cycle > 0 else BACKWARD
                speed = abs(duty_cycle)
                motor.run(direction)
                motor.setSpeed(speed)
                logging.debug(f"Motor {motor_num} set to speed {speed}, direction {direction}")


        except Exception as e:
            logging.error(f"Error setting duty cycle for motor {motor_num}: {e}")
            raise


    def stop(self, motor_num):
        """Stops a specific motor."""
        try:
            motor = self._get_motor(motor_num)
            if motor:
                motor.run(RELEASE)
                logging.info(f"Motor {motor_num} stopped.")
        except Exception as e:
            logging.error(f"Error stopping motor {motor_num}: {e}")
            raise


    def get_status(self, motor_num):
        """Retrieves status information for a specific motor."""
        status = {"motor_num": motor_num}
        try:
            motor = self._get_motor(motor_num)
            status["pwm_frequency"] = self._freq
            status["invert"] = motor._invert  # Access internal attribute
            status["last_duty_cycle"] = motor._duty  # Access internal attribute

        except Exception as e:
            logging.error(f"Error getting status for motor {motor_num}: {e}")
            raise

        return status



class DCMotor:
    """Class for controlling a single DC motor via the DCMotorHATExtra."""

    def __init__(self, motor_num, hat, freq=DEFAULT_PWM_FREQUENCY, invert=False):
        """Initializes the DC motor."""
        self.motor_num = motor_num
        self.hat = hat
        self.invert = invert
        self.last_duty_cycle = 0 # Initialize last duty cycle

        # Set initial frequency if provided
        if freq is not None:
            self.set_pwm_frequency(freq)

        # Stop the motor on initialization
        self.stop()

    def set_pwm_frequency(self, freq):
        """Sets the PWM frequency for the motor."""
        if self.hat.set_pwm_freq(freq):
            self.last_duty_cycle = 0 # Reset duty cycle on frequency change
            self.last_duty_cycle = self.last_duty_cycle

    def get_pwm_frequency(self):
        """Gets the PWM frequency for the motor."""
        return self.hat.get_pwm_freq()

    def invert_signal(self, invert):
        """Inverts the motor direction."""
        self.invert = invert
        self.stop() # Reset motor state after inversion

    def is_inverted(self):
        """Checks if the motor direction is inverted."""
        return self.invert

    def set_duty_cycle(self, duty_cycle):
        """Sets the duty cycle for the motor."""

        if not self.hat.is_duty_cycle_valid(duty_cycle):
            raise ValueError("Invalid duty cycle value.")

        duty_cycle = int(duty_cycle) # Ensure integer

        if duty_cycle == self.last_duty_cycle:
            return # No change, skip

        self.hat.set_dc(self.motor_num, duty_cycle * (-1 if self.invert else 1))
        self.last_duty_cycle = duty_cycle


    def set_speed(self, speed):
        """Sets the speed of the motor."""
        speed = max(-DC_MOTOR_MAX_SPEED, min(speed, DC_MOTOR_MAX_SPEED)) # Clamp
        self.set_duty_cycle(speed)

    def set_frequency(self, freq):
        """Alias for set_pwm_frequency."""
