# Helper function to move a servo smoothly
def move_servo(channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo smoothly to a target angle."""
    try:
        if not 0 <= channel <= 15:
            raise ValueError("Invalid servo channel.")
        if not 0 <= target_angle <= 180:
            raise ValueError("Invalid target angle.")

        current_angle = kit.servo[channel].angle or 0  # Get current angle, default to 0 if None

        # Optimize movement by checking if the servo is already at the target angle
        if current_angle == target_angle:
            return

        # Determine direction and create a range object
        if target_angle > current_angle:
            angle_range = range(current_angle, target_angle, step_size)
        else:
            angle_range = range(current_angle, target_angle, -step_size)

        # Move the servo in small increments
        for angle in angle_range:
            kit.servo[channel].angle = angle
            time.sleep(delay)

        # Set the final angle to ensure accuracy
        kit.servo[channel].angle = target_angle

    except ValueError as ve:
        print(ve)
    except Exception as e:
