#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and optimized driver for the DS1338 RTC chip
connected via I2C. It offers comprehensive error handling, performance
optimizations, and adheres to best practices for hardware interaction.
"""

import smbus2
from datetime import datetime, timezone
import contextlib

def bcd_to_int(bcd):
    """Decode a 2x4bit BCD to an integer."""
    try:
        return int(f"{bcd >> 4:01}{bcd & 0x0F:01}")
    except ValueError:
        raise ValueError("Invalid BCD value")

def int_to_bcd(n):
    """Encode an integer to BCD format."""
    try:
        tens, units = divmod(n, 10)
        return (tens << 4) | units
    except TypeError:
        raise ValueError("Invalid integer value")


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    # Register addresses
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    # Control register bits
    CH = 0x80  # Clock halt

    def __init__(self, twi=1, addr=0x68, debug=False):
        """Initialize the DS1338 driver.

        Args:
            twi (int): The I2C bus number (default: 1).
            addr (int): The I2C address of the DS1338 (default: 0x68).
            debug (bool): Enable debug logging (default: False).
        """
        self.twi = twi
        self.addr = addr
        self.debug = debug
        self._bus = None

    def _log(self, message):
        if self.debug:
            print(f"DS1338 (0x{self.addr:02X}): {message}")

    def _with_bus(self, func):
        """Context manager for I2C bus access."""
        @contextlib.contextmanager
        def bus_context():
            try:
                bus = smbus2.SMBus(self.twi)
                yield bus
            finally:
                if bus:
                    bus.close()

        with bus_context() as bus:
            try:
                self._bus = bus
                return func()
            except IOError as e:
                self._log(f"I2C Error: {e}")
                raise

    def _write_register(self, register, data):
        """Write data to a specific register."""
        try:
            with self._with_bus(lambda: self._bus.write_byte_data(self.addr, register, data)) as bus:
                pass
        except IOError as e:
            raise IOError(f"Error writing to register 0x{register:02X}: {e}")

    def _read_register(self, register):
        """Read data from a specific register."""
        try:
            with self._with_bus(lambda: self._bus.read_byte_data(self.addr, register)) as bus:
                return bus.read_byte()
        except IOError as e:
            raise IOError(f"Error reading from register 0x{register:02X}: {e}")


    def _read_time_register(self, register):
        """Read and decode a time register (BCD)."""
        try:
            data = self._read_register(register)
            return bcd_to_int(data)
        except (IOError, ValueError) as e:
            raise IOError(f"Error reading time register 0x{register:02X}: {e}")

    def _write_time_register(self, register, value):
        """Encode and write an integer to a time register (BCD)."""
        try:
            bcd_value = int_to_bcd(value)
            self._write_register(register, bcd_value)
        except (IOError, ValueError) as e:
            raise IOError(f"Error writing to time register 0x{register:02X}: {e}")

    def _read_all(self):
        """Read all time registers."""
        try:
            seconds = self._read_time_register(self.REG_SECONDS)
            minutes = self._read_time_register(self.REG_MINUTES)
            hours = self._read_time_register(self.REG_HOURS)
            day = self._read_time_register(self.REG_DAY)
            date = self._read_time_register(self.REG_DATE)
            month = self._read_time_register(self.REG_MONTH)
            year = self._read_time_register(self.REG_YEAR)
            return (year, month, date, day, hours, minutes, seconds)
        except IOError as e:
            raise IOError(f"Error reading all registers: {e}")


    def _write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all time registers."""

        # Validate input values before writing
        if not 1900 <= year <= 2100:
            raise ValueError("Year must be between 1900 and 2100")
        if not 1 <= month <= 12:
            raise ValueError("Month must be between 1 and 12")
        if not 1 <= date <= 31:
            raise ValueError("Date must be between 1 and 31")
        if not 1 <= day <= 7:
            raise ValueError("Day must be between 1 and 7")
        if not 0 <= hours <= 23:
            raise ValueError("Hours must be between 0 and 23")
        if not 0 <= minutes <= 59:
            raise ValueError("Minutes must be between 0 and 59")
        if not 0 <= seconds <= 59:
            raise ValueError("Seconds must be between 0 and 59")

        try:
            self._write_time_register(self.REG_SECONDS, seconds)
            self._write_time_register(self.REG_MINUTES, minutes)
            self._write_time_register(self.REG_HOURS, hours)  # Ensure 24-hour format
            self._write_time_register(self.REG_DAY, day)
            self._write_time_register(self.REG_DATE, date)
            self._write_time_register(self.REG_MONTH, month)
            self._write_time_register(self.REG_YEAR, year % 100) # Store only last two digits
            self._write_register(self.REG_CONTROL, 0x00) # Start the RTC
        except IOError as e:
            raise IOError(f"Error writing all registers: {e}")


    def read_datetime(self):
        """Read the current time from the RTC and return as a datetime object."""
        try:
