            return datetime(2000 + year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
        except IOError as e:
            raise IOError(f"Error reading datetime: {e}")


    def write_datetime(self, dt):
        """Write the given datetime object to the RTC."""
        try:
            self._write_all(dt.year % 100, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)
        except IOError as e:
            raise IOError(f"Error writing datetime: {e}")


    def write_now(self):
        """Write the current time (UTC) to the RTC."""
        try:
            self.write_datetime(datetime.now(timezone.utc))
        except IOError as e:
            raise IOError(f"Error writing current time: {e}")

    def read_now(self):
        """Read the current time from the RTC."""
        try:
            return self.read_datetime()
        except IOError as e:
            raise IOError(f"Error reading current time: {e}")

    def close(self):
        """Close the I2C bus connection."""
        if self._bus:
            self._bus.close()
            self._bus = None


def main():
    """Main function to demonstrate the DS1338 RTC driver."""
    try:
        rtc = DS1338(twi=1, addr=0x68, debug=True)
        rtc._log("DS1338 initialized successfully.")

        # Set the RTC to the current time
