import json
import time
import threading
import queue
import logging
from serial import Serial, SerialException
from flask import Flask, Response, request, jsonify, abort

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1
DATA_FILE = 'data.txt'
MAX_QUEUE_SIZE = 1000

# Global variables
data_queue = queue.Queue(maxsize=MAX_QUEUE_SIZE)
data_lock = threading.Lock()
app = Flask(__name__)
running = True

class SerialCommunicator:
    """
    Manages serial communication with the USB-serial device.
    Handles opening, closing, and sending/receiving data.
    """
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None

    def open(self):
        """Opens the serial port."""
        try:
            self.serial = Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Serial port {self.port} opened successfully.")
        except SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def close(self):
        """Closes the serial port."""
        if self.serial and self.serial.is_open:
            self.serial.close()
            logging.info(f"Serial port {self.port} closed.")

    def send(self, command):
        """Sends a command to the serial port and returns the response."""
        if not self.serial:
            raise SerialException("Serial port not open.")
        try:
            self.serial.write(command.encode())
            response = self.serial.readline().decode().strip()
            return response
        except SerialException as e:
            logging.error(f"Serial communication error: {e}")
            raise

    def receive_line(self):
        """Receives a line from the serial port with a timeout."""
        if not self.serial:
            raise SerialException("Serial port not open.")
        try:
            response = self.serial.readline().decode().strip()
            return response
        except SerialException as e:
            logging.error(f"Serial communication error: {e}")
            raise

class DataManager:
    """
    Manages the in-memory data store and file operations.
    """
    def __init__(self, data_file):
        self.data_file = data_file
        self.data = []
        self.load_data()

    def load_data(self):
        """Loads data from the file."""
        try:
            with open(self.data_file, 'r') as f:
                self.data = json.load(f)
            logging.info("Data loaded from file.")
        except FileNotFoundError:
            logging.warning("Data file not found. Starting with an empty data store.")
            self.data = []
        except json.JSONDecodeError:
            logging.error("Error decoding JSON from data file. Starting with an empty data store.")
            self.data = []
        except Exception as e:
            logging.error(f"Error loading data from file: {e}. Starting with an empty data store.")
            self.data = []

    def save_data(self):
        """Saves data to the file."""
        try:
            with open(self.data_file, 'w') as f:
                json.dump(self.data, f, indent=2)
            logging.info("Data saved to file.")
        except Exception as e:
            logging.error(f"Error saving data to file: {e}")

    def get_all(self):
        """Returns all data items."""
        with data_lock:
            return self.data

    def get_by_id(self, item_id):
        """Returns a data item by ID."""
        with data_lock:
            return next((item for item in self.data if item['id'] == item_id), None)

    def create(self, name, done):
        """Creates a new data item."""
        with data_lock:
            if not name:
                abort(400, "Name cannot be empty.")
            if not isinstance(done, bool):
                abort(400, "Done must be a boolean.")
            new_id = (max(item['id'] for item in self.data) + 1) if self.data else 1
            new_item = {'id': new_id, 'name': name, 'done': done}
            self.data.append(new_item)
            self.save_data()
            return new_item

def enqueue_data(data_item):
    """Adds data to the queue."""
    try:
        data_queue.put(data_item, timeout=1)
        logging.debug(f"Enqueued data item: {data_item}")
    except queue.Full:
        logging.warning("Data queue is full. Dropping the oldest item.")
        try:
            data_queue.get_nowait()  # Remove the oldest item
        except queue.Empty:
            pass
        data_queue.put(data_item, timeout=1) # Try to put the new item again

def data_processor(data_manager):
    """Processes data from the queue."""
    while running:
        try:
            data_item = data_queue.get(timeout=1)
            logging.info(f"Processing data item: {data_item}")
            # Simulate processing by sleeping for a short interval
            time.sleep(0.1)
            data_manager.save_data()  # Persist data after processing
        except queue.Empty:
            pass  # No data to process
        except Exception as e:
            logging.error(f"Error processing data: {e}")

def get_serial_data(serial_communicator):
    """Retrieves data from the serial port."""
    try:
        response = serial_communicator.receive_line()
        if response:
            logging.info(f"Received serial data: {response}")
            return response
        return None
    except SerialException as e:
        logging.error(f"Error receiving serial data: {e}")
        return None

def process_serial_data(data_manager, serial_communicator):
    """Processes serial data and enqueues it."""
    try:
        serial_data = get_serial_data(serial_communicator)
        if serial_data:
            # Simulate processing by adding a timestamp
            processed_data = {"timestamp": time.time(), "data": serial_data}
            enqueue_data(processed_data)
    except Exception as e:
        logging.error(f"Error processing serial data: {e}")

@app.route('/version', methods=['GET'])
def get_version():
    """Retrieves the software version from the serial port."""
    try:
        serial_communicator.open()
        response = serial_communicator.send('*IDN?\n')
        serial_communicator.close()
        logging.info(f"Serial version: {response}")
        return Response(response + '\n', mimetype='text/plain')
    except SerialException as e:
        logging.error(f"Failed to get serial version: {e}")
        abort(500, description="Failed to get serial version")
    except Exception as e:
        logging.error(f"Unexpected error getting serial version: {e}")
        abort(500, description="Unexpected error getting serial version")
    finally:
        serial_communicator.close()

@app.route('/data', methods=['GET'])
def get_all_data():
    """Retrieves all data items."""
    data_manager = DataManager(DATA_FILE)
    all_data = data_manager.get_all()
    return jsonify(all_data)

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    """Retrieves a data item by ID."""
    data_manager = DataManager(DATA_FILE)
    data_item = data_manager.get_by_id(item_id)
    if data_item:
        return jsonify(data_item)
    else:
        abort(404, description="Data item not found")

@app.route('/data', methods=['POST'])
def create_data_item():
    """Creates a new data item."""
    name = request.json.get('name')
    done = request.json.get('done')
    data_manager = DataManager(DATA_FILE)
    new_item = data_manager.create(name, done)
    return jsonify(new_item), 201

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global running
    logging.info("Received shutdown signal. Exiting gracefully...")
    running = False

def main():
    """Main function to start the Flask application."""
    global running
    import signal
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize SerialCommunicator
    serial_communicator = SerialCommunicator(SERIAL_PORT, SERIAL_BAUDRATE, SERIAL_TIMEOUT)

    # Initialize DataManager
    data_manager = DataManager(DATA_FILE)

    # Start data processing thread
    data_thread = threading.Thread(target=data_processor, args=(data_manager,))
    data_thread.daemon = True
    data_thread.start()

    try:
        app.run(debug=False, host='0.0.0.0', port=5000)
    except Exception as e:
        logging.error(f"Error running Flask app: {e}")
    finally:
        logging.info("Shutting down...")
        running = False
        serial_communicator.close()
        data_thread.join()  # Wait for the data thread to finish
        logging.info("Shutdown complete.")

if __name__ == '__main__':
    main()

