            with open(self.data_file, 'r') as f:
                self.data = json.load(f)
            logging.info("Data loaded from file.")
        except FileNotFoundError:
            logging.warning("Data file not found. Starting with an empty data store.")
            self.data = []
        except json.JSONDecodeError:
            logging.error("Error decoding JSON from data file. Starting with an empty data store.")
            self.data = []
        except Exception as e:
            logging.error(f"Error loading data from file: {e}. Starting with an empty data store.")
            self.data = []

    def save_data(self):
        """Saves data to the file."""
        try:
            with open(self.data_file, 'w') as f:
                json.dump(self.data, f, indent=2)
            logging.info("Data saved to file.")
        except Exception as e:
            logging.error(f"Error saving data to file: {e}")

    def get_all(self):
        """Returns all data items."""
        with data_lock:
            return self.data

    def get_by_id(self, item_id):
        """Returns a data item by ID."""
        with data_lock:
            return next((item for item in self.data if item['id'] == item_id), None)

    def create(self, name, done):
        """Creates a new data item."""
        with data_lock:
            if not name:
                abort(400, "Name cannot be empty.")
            if not isinstance(done, bool):
                abort(400, "Done must be a boolean.")
            new_id = (max(item['id'] for item in self.data) + 1) if self.data else 1
            new_item = {'id': new_id, 'name': name, 'done': done}
            self.data.append(new_item)
            self.save_data()
            return new_item

def enqueue_data(data_item):
    """Adds data to the queue."""
    try:
        data_queue.put(data_item, timeout=1)
        logging.debug(f"Enqueued data item: {data_item}")
    except queue.Full:
        logging.warning("Data queue is full. Dropping the oldest item.")
        try:
            data_queue.get_nowait()  # Remove the oldest item
        except queue.Empty:
            pass
        data_queue.put(data_item, timeout=1) # Try to put the new item again

def data_processor(data_manager):
    """Processes data from the queue."""
    while running:
        try:
            data_item = data_queue.get(timeout=1)
            logging.info(f"Processing data item: {data_item}")
            # Simulate processing by sleeping for a short interval
            time.sleep(0.1)
            data_manager.save_data()  # Persist data after processing
        except queue.Empty:
            pass  # No data to process
        except Exception as e:
            logging.error(f"Error processing data: {e}")

def get_serial_data(serial_communicator):
    """Retrieves data from the serial port."""
    try:
        response = serial_communicator.receive_line()
        if response:
            logging.info(f"Received serial data: {response}")
            return response
        return None
    except SerialException as e:
        logging.error(f"Error receiving serial data: {e}")
        return None

def process_serial_data(data_manager, serial_communicator):
    """Processes serial data and enqueues it."""
    try:
        serial_data = get_serial_data(serial_communicator)
        if serial_data:
            # Simulate processing by adding a timestamp
            processed_data = {"timestamp": time.time(), "data": serial_data}
            enqueue_data(processed_data)
    except Exception as e:
        logging.error(f"Error processing serial data: {e}")

@app.route('/version', methods=['GET'])
