        response = serial_communicator.send('*IDN?\n')
        serial_communicator.close()
        logging.info(f"Serial version: {response}")
        return Response(response + '\n', mimetype='text/plain')
    except SerialException as e:
        logging.error(f"Failed to get serial version: {e}")
        abort(500, description="Failed to get serial version")
    except Exception as e:
        logging.error(f"Unexpected error getting serial version: {e}")
        abort(500, description="Unexpected error getting serial version")
    finally:
        serial_communicator.close()

@app.route('/data', methods=['GET'])
def get_all_data():
    """Retrieves all data items."""
    data_manager = DataManager(DATA_FILE)
    all_data = data_manager.get_all()
    return jsonify(all_data)

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    """Retrieves a data item by ID."""
    data_manager = DataManager(DATA_FILE)
    data_item = data_manager.get_by_id(item_id)
    if data_item:
        return jsonify(data_item)
    else:
        abort(404, description="Data item not found")

@app.route('/data', methods=['POST'])
def create_data_item():
    """Creates a new data item."""
    name = request.json.get('name')
    done = request.json.get('done')
    data_manager = DataManager(DATA_FILE)
    new_item = data_manager.create(name, done)
    return jsonify(new_item), 201

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global running
    logging.info("Received shutdown signal. Exiting gracefully...")
    running = False

def main():
    """Main function to start the Flask application."""
    global running
    import signal
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize SerialCommunicator
    serial_communicator = SerialCommunicator(SERIAL_PORT, SERIAL_BAUDRATE, SERIAL_TIMEOUT)

    # Initialize DataManager
    data_manager = DataManager(DATA_FILE)

    # Start data processing thread
    data_thread = threading.Thread(target=data_processor, args=(data_manager,))
    data_thread.daemon = True
    data_thread.start()

    try:
        app.run(debug=False, host='0.0.0.0', port=5000)
    except Exception as e:
        logging.error(f"Error running Flask app: {e}")
    finally:
        logging.info("Shutting down...")
        running = False
        serial_communicator.close()
        data_thread.join()  # Wait for the data thread to finish
        logging.info("Shutdown complete.")

if __name__ == '__main__':
    main()

