# Reads pulse oximeter data from a serial port and prints heart rate and SpO2.
# Target: Raspberry Pi 3 Model B+
# Context: Wearable technology

import serial
import time

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

def read_oximeter_data(serial_connection):
    """
    Reads a line from the serial port, decodes it, and splits it into heart rate and SpO2.
    """
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return line.split(',')
        return None
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return None
    except UnicodeDecodeError as e:
        print(f"Decoding error: {e}")
        return None

def process_data(data):
    """
    Processes the split data and prints heart rate and SpO2 if available.
    """
    if data and len(data) == 2:
        try:
            heart_rate = int(data[0])
            spo2 = int(data[1])
            print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')
        except ValueError:
            print("Invalid data format received.")
    else:
        print("Incomplete data received.")

def main():
    """
    Main function to read and process pulse oximeter data.
    """
    serial_connection = None
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to serial port {SERIAL_PORT}")

        while True:
            data = read_oximeter_data(serial_connection)
            process_data(data)
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

