SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1

# In-memory data store (list of dictionaries)
DATA_STORE = [{"id": 1, "name": "Item 1", "done": False}, 
              {"id": 2, "name": "Item 2", "done": False}]

# Initialize serial port
serial_port = None

def initialize_serial():
    """Initializes the serial port with error handling."""
    global serial_port
    try:
        serial_port = Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT)
        logging.info(f"Serial port {SERIAL_PORT} initialized.")
    except SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        serial_port = None  # Ensure serial_port is None if initialization fails

def close_serial_port():
    """Closes the serial port if it's open."""
    global serial_port
    if serial_port and serial_port.is_open:
        try:
            serial_port.close()
            logging.info("Serial port closed.")
        except SerialException as e:
            logging.error(f"Failed to close serial port: {e}")
        finally:
            serial_port = None

def get_serial_data():
    """Reads data from the serial port with error handling."""
    if serial_port and serial_port.is_open:
        try:
            time.sleep(0.1)  # Give some time for data to arrive
            data = serial_port.read_all().decode('utf-8', errors='ignore')
            return data
        except SerialException as e:
            logging.error(f"Error reading from serial port: {e}")
            return None
    else:
        logging.warning("Serial port is not open.")
        return None

def send_serial_data(data):
    """Sends data to the serial port with error handling."""
    if serial_port and serial_port.is_open:
        try:
            serial_port.write(data.encode())
            logging.debug(f"Sent data to serial port: {data}")
        except SerialException as e:
            logging.error(f"Error writing to serial port: {e}")
    else:
        logging.warning("Serial port is not open.")


